update public.items i
set explanation_en = v.new
from (values
  ($c$espresso$c$, $c$A small, strong shot of coffee. The base of most coffee drinks.$c$, $c$A tiny, strong cup of coffee, a sip or two, with a brown foam on top. Most café coffees are made from it.$c$),
